def _styles() -> dict[str, ParagraphStyle]:
    return {
        "title": ParagraphStyle("pTitle", fontName="Helvetica-Bold", fontSize=17,
                                textColor=WHITE, alignment=TA_CENTER, spaceAfter=3),
        "subtitle": ParagraphStyle("pSubtitle", fontName="Helvetica", fontSize=10,
                                   textColor=LIGHT_GOLD, alignment=TA_CENTER),
        "section": ParagraphStyle("pSection", fontName="Helvetica-Bold", fontSize=12,
                                  textColor=NAVY, spaceBefore=12, spaceAfter=4),
        "body": ParagraphStyle("pBody", fontName="Helvetica", fontSize=9,
                               textColor=colors.black, leading=13, spaceAfter=5),
        "th": ParagraphStyle("pTh", fontName="Helvetica-Bold", fontSize=8, textColor=WHITE),
        "th_r": ParagraphStyle("pThR", fontName="Helvetica-Bold", fontSize=8,
                               textColor=WHITE, alignment=TA_RIGHT),
        "td": ParagraphStyle("pTd", fontName="Helvetica", fontSize=7.5, leading=9.5),
        "td_b": ParagraphStyle("pTdB", fontName="Helvetica-Bold", fontSize=7.5, leading=9.5),
        "td_r": ParagraphStyle("pTdR", fontName="Helvetica", fontSize=7.5,
                               leading=9.5, alignment=TA_RIGHT),
        "td_rb": ParagraphStyle("pTdRB", fontName="Helvetica-Bold", fontSize=7.5,
                                leading=9.5, alignment=TA_RIGHT),
        "opt_head": ParagraphStyle("pOptHead", fontName="Helvetica-Bold", fontSize=10,
                                   textColor=NAVY, spaceAfter=4),
        "opt_body": ParagraphStyle("pOptBody", fontName="Helvetica", fontSize=8,
                                   leading=11.5, spaceAfter=3),
        "check": ParagraphStyle("pCheck", fontName="Helvetica", fontSize=8.5,
                                leading=13, leftIndent=10, spaceAfter=2),
        "caveat": ParagraphStyle("pCaveat", fontName="Helvetica", fontSize=6.5,
                                 textColor=DARK_GREY, leading=9, alignment=TA_LEFT),
    }


def _footer(canvas: Any, doc: Any) -> None:
    """Gold rule plus the Camelot OS attribution line on every page."""
    canvas.saveState()
    width, _ = doc.pagesize
    y = 0.45 * inch
    canvas.setStrokeColor(GOLD)
    canvas.setLineWidth(1)
    canvas.line(0.5 * inch, y + 12, width - 0.5 * inch, y + 12)
    canvas.setFont("Helvetica", 7)
    canvas.setFillColor(colors.grey)
    canvas.drawString(
        0.5 * inch, y,
        f"Generated by Camelot OS · Perseus | {date.today().strftime('%B %d, %Y')}",
    )
    canvas.drawRightString(width - 0.5 * inch, y, f"Page {canvas.getPageNumber()}")
    canvas.restoreState()


