def _header_band(analysis: VarianceAnalysis, st: dict) -> Table:
    units = f"{analysis.unit_count} units" if analysis.unit_count else "unit count not supplied"
    detail = " · ".join(
        p for p in (analysis.address, units, analysis.building_type, analysis.market) if p
    )

    band = Table(
        [
            [Paragraph("CAMELOT PROPERTY MANAGEMENT SERVICES CORP", st["subtitle"])],
            [Paragraph(analysis.property_name.upper(), st["title"])],
            [Paragraph(detail, st["subtitle"])],
            [Paragraph(
                f"{analysis.period_label} Variance &amp; Savings Report · "
                f"{date.today().strftime('%B %d, %Y')}", st["subtitle"])],
        ],
        colWidths=[10.0 * inch],
    )
    band.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, -1), NAVY),
        ("TOPPADDING", (0, 0), (-1, -1), 5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
        ("LEFTPADDING", (0, 0), (-1, -1), 16),
        ("RIGHTPADDING", (0, 0), (-1, -1), 16),
        ("LINEBELOW", (0, -1), (-1, -1), 2.5, GOLD),
    ]))
    return band


def _section_head(title: str, st: dict) -> list[Any]:
    return [Paragraph(title.upper(), st["section"]),
            HRFlowable(width="100%", thickness=1.2, color=GOLD, spaceAfter=6)]


def summary_paragraphs(analysis: VarianceAnalysis, proposal: FeeProposal) -> list[str]:
    """
    The plain-language read on the period. Each sentence carries one figure, and
    each figure arrives with what it means rather than on its own.
    """
    variance = analysis.budget_variance
    direction = "over" if variance > 0 else "under"
    paragraphs: list[str] = []

    if analysis.total_budget_period:
        paragraphs.append(
            f"The building ran <b>{direction} its budget share for "
            f"{analysis.period_label} by ${abs(variance):,.0f}</b>, on a prorated "
            f"share of ${analysis.total_budget_period:,.0f} "
            f"({abs(analysis.budget_variance_pct) * 100:.1f}% {direction}). "
            f"{_baseline_sentence(analysis)}"
        )
    else:
        paragraphs.append(
            f"No budget line matched the categories in this report, so "
            f"{analysis.period_label} is reported against the portfolio only. "
            f"{_baseline_sentence(analysis)}"
        )

    flagged = analysis.flagged_lines
    if flagged:
        names = _join_labels([ln.label for ln in flagged])
        paragraphs.append(
            f"<b>{len(flagged)} line{'s' if len(flagged) != 1 else ''} came in far "
            f"enough over budget to warrant a question</b> — {names}. Each one needs "
            f"its invoices pulled before the variance is treated as a price problem "
            f"rather than a timing one."
        )
    elif analysis.total_budget_period:
        paragraphs.append(
            "No category ran far enough over its budget share to warrant a question "
            "this period."
        )

    if analysis.portfolio_savings_annual > 0:
        paragraphs.append(
            f"Set against what Camelot pays across comparable buildings, this "
            f"period's run-rate is <b>${analysis.portfolio_savings_annual:,.0f} a year "
            f"above the portfolio</b> on the lines with comparable evidence — "
            f"${analysis.portfolio_savings_period:,.0f} of that falls in "
            f"{analysis.period_label} itself. That gap is addressable, and the "
            f"mechanism for each line is named in the table below."
        )
    elif analysis.benchmark_coverage:
        paragraphs.append(
            "Every category with comparable evidence sits at or below the portfolio "
            "average, so there is no addressable gap to price this period."
        )
    else:
        paragraphs.append(
            "No comparable Camelot building of this size is on file yet, so the "
            "portfolio check could not run. Seed portfolio_benchmarks from the "
            "monthly management reports and this half of the report fills in."
        )

    if analysis.seasonal_categories:
        paragraphs.append(
            f"<b>Seasonality caveat:</b> {_join_labels(analysis.seasonal_categories)} "
            f"do not arrive in even periods. Their budget share here is a flat split, "
            f"so read a variance on those lines against the same period last year "
            f"before acting on it."
        )

    return paragraphs


def _baseline_sentence(analysis: VarianceAnalysis) -> str:
    return analysis.baseline.describe() if analysis.baseline else ""


def _variance_table(analysis: VarianceAnalysis, st: dict) -> Table:
    """Budget vs. actual for the period, worst overrun first."""
    rows: list[list[Any]] = [[
        Paragraph("Line Item", st["th"]),
        Paragraph("Budget Share", st["th_r"]),
        Paragraph(f"{analysis.period_label} Actual", st["th_r"]),
        Paragraph("Variance", st["th_r"]),
        Paragraph("%", st["th_r"]),
        Paragraph("Status", st["th"]),
        Paragraph("What Drives It / What To Check", st["th"]),
    ]]

    ordered = sorted(
        analysis.lines,
        key=lambda ln: (ln.budget_period is None, -ln.budget_variance),
    )

    flag_rows: list[int] = []
    quiet_rows: list[int] = []

    for line in ordered:
        index = len(rows)
        if line.budget_flag == FLAG_INVESTIGATE:
            flag_rows.append(index)
        elif line.budget_flag == FLAG_NO_BASELINE:
            quiet_rows.append(index)

        label = line.label + (" *" if line.scope_protected else "") + ("  †" if line.seasonal else "")
        if line.budget_period is None:
            budget_cell, variance_cell, pct_cell = "—", "—", "—"
        else:
            budget_cell = f"${line.budget_period:,.0f}"
            variance_cell = (
                f"+${line.budget_variance:,.0f}" if line.budget_variance >= 0
                else f"(${abs(line.budget_variance):,.0f})"
            )
            pct_cell = f"{line.budget_variance_pct * 100:+.0f}%"

        rows.append([
            Paragraph(label, st["td_b"]),
            Paragraph(budget_cell, st["td_r"]),
            Paragraph(f"${line.actual_period:,.0f}", st["td_r"]),
            Paragraph(variance_cell, st["td_rb"] if line.flagged else st["td_r"]),
            Paragraph(pct_cell, st["td_r"]),
            Paragraph(STATUS_TEXT.get(line.budget_flag, line.budget_flag), st["td"]),
            Paragraph(_variance_note(line), st["td"]),
        ])

    total_variance = analysis.budget_variance
    rows.append([
        Paragraph("TOTAL", st["td_b"]),
        Paragraph(f"${analysis.total_budget_period:,.0f}", st["td_rb"]),
        Paragraph(f"${analysis.total_actual_budgeted_period:,.0f}", st["td_rb"]),
        Paragraph(
            f"+${total_variance:,.0f}" if total_variance >= 0
            else f"(${abs(total_variance):,.0f})", st["td_rb"]),
        Paragraph(f"{analysis.budget_variance_pct * 100:+.1f}%", st["td_rb"]),
        Paragraph(
            f"{len(analysis.flagged_lines)} flagged", st["td_b"]),
        Paragraph(_totals_basis_note(analysis), st["td"]),
    ])

    table = Table(
        rows,
        colWidths=[w * inch for w in (1.6, 0.85, 0.9, 0.85, 0.5, 0.75, 4.55)],
        repeatRows=1,
    )
    style = [
        ("BACKGROUND", (0, 0), (-1, 0), NAVY),
        ("LINEBELOW", (0, 0), (-1, 0), 2, GOLD),
        ("GRID", (0, 0), (-1, -1), 0.4, MID_GREY),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("TOPPADDING", (0, 0), (-1, -1), 4),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
        ("LEFTPADDING", (0, 0), (-1, -1), 5),
        ("RIGHTPADDING", (0, 0), (-1, -1), 5),
        ("BACKGROUND", (0, -1), (-1, -1), LIGHT_GOLD),
        ("LINEABOVE", (0, -1), (-1, -1), 1.5, GOLD),
    ]
    for index in flag_rows:
        style.append(("BACKGROUND", (0, index), (-1, index), colors.HexColor("#FBEEEC")))
        style.append(("TEXTCOLOR", (5, index), (5, index), RED))
    for index in quiet_rows:
        style.append(("BACKGROUND", (0, index), (-1, index), LIGHT_GREY))
        style.append(("TEXTCOLOR", (0, index), (-1, index), DARK_GREY))
    table.setStyle(TableStyle(style))
    return table


def _totals_basis_note(analysis: VarianceAnalysis) -> str:
    """
    State what the totals row does and does not count.

    The row only totals the lines carrying a budget share, so when some lines
    have none the Actual column will not add up to this figure. Say so, and give
    the full period spend, rather than leaving the owner to find the gap.
    """
    budgeted = len(analysis.budgeted_lines)
    unbudgeted = len(analysis.lines) - budgeted
    if not unbudgeted:
        return "Totals cover every line on the report."
    subject = "line" if unbudgeted == 1 else "lines"
    verb = "is" if unbudgeted == 1 else "are"
    basis = "the one line" if budgeted == 1 else f"the {budgeted} lines"
    return (
        f"Totals cover {basis} with a budget share. {unbudgeted} {subject} without "
        f"one {verb} listed for completeness and excluded here; total spend for the "
        f"period was ${analysis.total_actual_period:,.0f}."
    )


def _variance_note(line: VarianceLine) -> str:
    """One sentence on what the variance means for this line."""
    if line.budget_flag == FLAG_NO_BASELINE:
        return (
            "No matching line in the budget baseline. Add it to the budget or "
            "confirm the spend belongs to another category."
        )
    if line.budget_flag == FLAG_INVESTIGATE:
        base = (
            f"Running ${line.budget_variance:,.0f} over the period share. "
            if line.budget_variance
            else ""
        )
        if line.seasonal:
            return base + (
                "This category is seasonal, so compare against the same period last "
                "year before treating the overrun as a price problem."
            )
        return base + "Pull the invoices behind the line for the period."
    if line.budget_flag == FLAG_UNDERSPENT:
        return (
            "Under the period share. Usually deferred work or a bill that has not "
            "landed yet — confirm which, so the year-end position is not a surprise."
        )
    return "Tracking within the budget share for the period."


def _portfolio_table(analysis: VarianceAnalysis, st: dict) -> Table:
    """Annualized run-rate against the portfolio average, largest gap first."""
    rows: list[list[Any]] = [[
        Paragraph("Line Item", st["th"]),
        Paragraph("Annualized Run-Rate", st["th_r"]),
        Paragraph("Camelot Comparable Evidence", st["th"]),
        Paragraph("Portfolio Target (Est.)", st["th_r"]),
        Paragraph("Est. Annual Savings", st["th_r"]),
        Paragraph("%", st["th_r"]),
        Paragraph("How We Get There", st["th"]),
    ]]

    ordered = (
        sorted(analysis.savings_lines, key=lambda ln: ln.portfolio_savings_annual, reverse=True)
        + [ln for ln in analysis.addressed_lines if ln.portfolio_savings_annual <= 0]
        + analysis.not_addressed_lines
    )

    at_average_rows: list[int] = []
    not_addressed_rows: list[int] = []

    for line in ordered:
        index = len(rows)
        if not line.addressed:
            not_addressed_rows.append(index)
        elif line.portfolio_savings_annual <= 0:
            at_average_rows.append(index)

        label = line.label + (" *" if line.scope_protected else "")
        savings = (
            f"${line.portfolio_savings_annual:,.0f}"
            if line.portfolio_savings_annual > 0 else "—"
        )
        pct = (
            f"{line.portfolio_savings_annual / line.annualized_actual * 100:.0f}%"
            if line.portfolio_savings_annual > 0 and line.annualized_actual else "0%"
        )

        rows.append([
            Paragraph(label, st["td_b"]),
            Paragraph(f"${line.annualized_actual:,.0f}", st["td_r"]),
            Paragraph(line.evidence, st["td"]),
            Paragraph(f"${line.portfolio_target_annual:,.0f}", st["td_r"]),
            Paragraph(savings, st["td_rb"] if line.portfolio_savings_annual > 0 else st["td_r"]),
            Paragraph(pct, st["td_r"]),
            Paragraph(line.recommendation, st["td"]),
        ])

    rows.append([
        Paragraph("TOTAL", st["td_b"]),
        Paragraph(f"${analysis.annualized_actual:,.0f}", st["td_rb"]),
        Paragraph(
            f"{analysis.benchmark_coverage} categor"
            f"{'y' if analysis.benchmark_coverage == 1 else 'ies'} with Camelot comparables",
            st["td"]),
        Paragraph(
            f"${analysis.annualized_actual - analysis.portfolio_savings_annual:,.0f}",
            st["td_rb"]),
        Paragraph(f"${analysis.portfolio_savings_annual:,.0f}", st["td_rb"]),
        Paragraph(f"{analysis.savings_pct_of_annualized * 100:.1f}%", st["td_rb"]),
        Paragraph(
            "Addressable savings as a share of the annualized run-rate.", st["td"]),
    ])

    table = Table(
        rows,
        colWidths=[w * inch for w in (1.45, 0.9, 2.4, 0.85, 0.85, 0.35, 3.2)],
        repeatRows=1,
    )
    style = [
        ("BACKGROUND", (0, 0), (-1, 0), NAVY),
        ("LINEBELOW", (0, 0), (-1, 0), 2, GOLD),
        ("GRID", (0, 0), (-1, -1), 0.4, MID_GREY),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("TOPPADDING", (0, 0), (-1, -1), 4),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
        ("LEFTPADDING", (0, 0), (-1, -1), 5),
        ("RIGHTPADDING", (0, 0), (-1, -1), 5),
        ("BACKGROUND", (0, -1), (-1, -1), LIGHT_GOLD),
        ("LINEABOVE", (0, -1), (-1, -1), 1.5, GOLD),
    ]
    for index in at_average_rows:
        style.append(("BACKGROUND", (0, index), (-1, index), LIGHT_GREY))
    for index in not_addressed_rows:
        style.append(("BACKGROUND", (0, index), (-1, index), colors.HexColor("#FAF6EC")))
        style.append(("TEXTCOLOR", (0, index), (-1, index), DARK_GREY))
    table.setStyle(TableStyle(style))
    return table


def _coverage_note(analysis: VarianceAnalysis, st: dict) -> list[Any]:
    """What the report could not reach, stated before anyone has to ask."""
    notes: list[Any] = []
    not_addressed = analysis.not_addressed_lines
    if not_addressed:
        total = sum(ln.annualized_actual for ln in not_addressed)
        names = _join_labels([ln.label for ln in not_addressed])
        notes.append(Paragraph(
            f"<b>Not addressed:</b> ${total:,.0f} of annualized spend across "
            f"{len(not_addressed)} line{'s' if len(not_addressed) != 1 else ''} "
            f"({names}) has no comparable Camelot building on file at this size. "
            f"Those lines are excluded from the savings total and need a records and "
            f"vendor-bid review before any target can be set.", st["body"]))
    else:
        notes.append(Paragraph(
            "Every expense line in the report mapped to a Camelot expense category "
            "with at least one comparable building on file.", st["body"]))

    for warning in analysis.parse_warnings:
        notes.append(Paragraph(f"<b>Parse note:</b> {warning}", st["body"]))
    if analysis.needs_review:
        notes.append(Paragraph(
            "<b>Review before sending:</b> the parsed figures could not be "
            "reconciled against a total stated in the source file. Confirm each line "
            "against the report before this goes to a client.", st["body"]))
    return notes


def _fee_proposal(proposal: FeeProposal, st: dict) -> Table:
    """Both options side by side, recommended one on a gold ground."""

    def column(option, label: str) -> list[Any]:
        recommended = option.model == proposal.recommended_model
        heading = f"{label}{'  ·  RECOMMENDED' if recommended else ''}"
        cells: list[Any] = [
            Paragraph(heading, st["opt_head"]),
            Paragraph(option.headline, st["opt_body"]),
            Spacer(1, 3),
        ]
        cells.extend(Paragraph(f"• {point}", st["opt_body"]) for point in option.talking_points)
        return cells

    table = Table(
        [[
            column(
                proposal.one_time,
                f"Option A — One-Time Fee "
                f"({proposal.one_time.camelot_share_pct * 100:.0f}% of "
                f"{proposal.period_label} savings)",
            ),
            column(
                proposal.uplift,
                f"Option B — Management-Fee Uplift "
                f"({proposal.uplift.camelot_share_pct * 100:.0f}% of annualized savings)",
            ),
        ]],
        colWidths=[4.9 * inch, 4.9 * inch],
    )

    recommended_col = 0 if proposal.recommended_model == ONE_TIME else 1
    other_col = 1 - recommended_col
    table.setStyle(TableStyle([
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("BACKGROUND", (recommended_col, 0), (recommended_col, 0), LIGHT_GOLD),
        ("BACKGROUND", (other_col, 0), (other_col, 0), LIGHT_GREY),
        ("BOX", (recommended_col, 0), (recommended_col, 0), 1.5, GOLD),
        ("BOX", (other_col, 0), (other_col, 0), 0.5, MID_GREY),
        ("TOPPADDING", (0, 0), (-1, -1), 10),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 10),
        ("LEFTPADDING", (0, 0), (-1, -1), 12),
        ("RIGHTPADDING", (0, 0), (-1, -1), 12),
    ]))
    return table


