# Public API
# ---------------------------------------------------------------------------

def generate_report(
    analysis: VarianceAnalysis,
    proposal: FeeProposal,
    output_dir: str,
    report_id: Optional[str] = None,
) -> str:
    """
    Render the period variance PDF and return its path.

    Landscape letter — the seven-column comparison tables need the width.
    """
    os.makedirs(output_dir, exist_ok=True)
    slug = (
        "".join(c if c.isalnum() else "_" for c in analysis.property_name).strip("_").lower()
        or "building"
    )
    period_slug = (
        f"{analysis.year}_{analysis.quarter}".lower() if analysis.quarter else str(analysis.year)
    )
    suffix = (report_id or date.today().isoformat())[:8]
    output_path = os.path.join(output_dir, f"perseus_{slug}_{period_slug}_{suffix}.pdf")

    st = _styles()
    buf = io.BytesIO()
    doc = SimpleDocTemplate(
        buf,
        pagesize=landscape(letter),
        leftMargin=0.5 * inch,
        rightMargin=0.5 * inch,
        topMargin=0.5 * inch,
        bottomMargin=0.75 * inch,
        title=f"Camelot {analysis.period_label} Variance Report — {analysis.property_name}",
        author="Camelot Property Management Services Corp",
    )

    story: list[Any] = [_header_band(analysis, st), Spacer(1, 0.16 * inch)]

    story.extend(_section_head(f"1. Where {analysis.period_label} Landed", st))
    story.extend(Paragraph(text, st["body"]) for text in summary_paragraphs(analysis, proposal))

    story.extend(_section_head(f"2. Budget vs. Actual — {analysis.period_label}", st))
    story.append(_variance_table(analysis, st))

    story.extend(_section_head("3. Annualized Run-Rate vs. Camelot Portfolio Average", st))
    story.append(_portfolio_table(analysis, st))

    story.extend(_section_head("4. Coverage Disclosure", st))
    story.extend(_coverage_note(analysis, st))

    story.extend(_section_head(f"5. Fee Proposal — {analysis.period_label} Only", st))
    story.append(Paragraph(proposal.rationale, st["body"]))
    story.append(Paragraph(
        f"This proposal prices the savings identified in {analysis.period_label}. It "
        f"is not cumulative with a prior period and is not netted against any annual "
        f"budget proposal for the same building.", st["body"]))
    story.append(Spacer(1, 0.06 * inch))
    story.append(_fee_proposal(proposal, st))

    story.extend(_section_head("6. Follow-Up / Next Steps", st))
    story.extend(Paragraph(f"☐  {step}", st["check"]) for step in next_steps(analysis, proposal))

    story.append(Spacer(1, 0.16 * inch))
    story.append(KeepTogether([
        HRFlowable(width="100%", thickness=1, color=MID_GREY, spaceAfter=5),
        Paragraph(
            f"<b>Legend:</b>  * = fire/life-safety, elevator safety, or statutory "
            f"scope — rebid at identical scope only, never reduced.  &nbsp;|&nbsp;  "
            f"† = seasonal category, budget share is a flat split.  &nbsp;|&nbsp;  "
            f"\"Investigate\" = more than {_overrun_threshold_pct():.0f}% over the "
            f"period's budget share.  &nbsp;|&nbsp;  Shaded rows carry no savings "
            f"claim.", st["caveat"]),
        Spacer(1, 4),
        Paragraph(CAVEAT, st["caveat"]),
    ]))

    doc.build(story, onFirstPage=_footer, onLaterPages=_footer)

    with open(output_path, "wb") as f:
        f.write(buf.getvalue())

    logger.info("Perseus variance PDF written to %s", output_path)
    return output_path


def _overrun_threshold_pct() -> float:
    return float(load_config()["variance"]["budget_overrun_flag_pct"]) * 100
